customCSS:
.t, .history { color: #8c8fa1; }
.join { color: #40a02b; }
.part, .quit { color: #8c8fa1; }
.kick, .error { color: #d20f39; }
.notice { color: #df8e1d; }
.action { color: #8839ef; }
.mode, .nick, .topic, .server { color: #179299; }
.highlight { color: #4c4f69; background-color: #ccd0da; border-left: 3px solid #8839ef; padding-left: 8px; }
.reply { color: #8c8fa1; border-left: 2px solid #1e66f5; padding-left: 6px; }
.oper { color: #eff1f5; background-color: #df8e1d; }
.reactions { color: #1e66f5; background-color: #e6e9ef; }
.card { background-color: #e6e9ef; border-color: #8c8fa1; }
.card-title { color: #1e66f5; }
.card-desc { color: #8c8fa1; }
.daychange { color: #8c8fa1; border-color: #e6e9ef; }
